  <body>
    <main>
      <section class="card" aria-labelledby="form-title">
        <h1 id="form-title">Terms of use</h1>
        <p class="intro">Confirm your agreement before continuing.</p>
        <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <input
              id="terms-consent"
              name="termsConsent"
              type="checkbox"
              required
              aria-describedby="terms-helper terms-error"
            >
            <label for="terms-consent">
              I agree to the terms of use
              <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <p id="terms-helper" class="helper">Required to create or access your account.</p>
            <p id="terms-error" class="error" hidden>Error: You must agree to the terms of use to continue.</p>
          </div>

          <button type="submit">Continue</button>
          <p id="form-status" class="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#terms-consent");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      function setConsentError(shouldShow) {
        error.hidden = !shouldShow;
        if (shouldShow) {
          checkbox.setAttribute("aria-invalid", "true");
        } else {
          checkbox.removeAttribute("aria-invalid");
        }
      }

      form.addEventListener("submit", (event) => {
        status.textContent = "";

        if (!checkbox.checked) {
          event.preventDefault();
          setConsentError(true);
          checkbox.focus();
          return;
        }

        event.preventDefault();
        setConsentError(false);
        status.textContent = "Consent recorded. Thank you.";
      });

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          setConsentError(false);
        }
      });
    </script>
  </body>
